def test_find_duplicates_ignores_case_and_spaces():
    items = [Item("A-100", "a"), Item("a-100 ", "b"), Item("B-200", "c")]
    assert find_duplicates(items) == ["A-100"]

from decimal import Decimal

from inventory import Item


def test_sku_is_upper_cased():
    assert Item(" ab-100 ", "Anchor").sku == "AB-100"


def test_stock_value():
    assert Item("A-100", "Anchor", on_hand=3, unit_cost="0.335").stock_value == Decimal("1.01")
